package cl.bancoxyz.payment;import io.github.resilience4j.circuitbreaker.annotation.CircuitBreaker;import io.github.resilience4j.retry.annotation.Retry;import java.util.Map;import org.springframework.beans.factory.annotation.Value;import org.springframework.cloud.client.loadbalancer.LoadBalanced;import org.springframework.stereotype.Service;import org.springframework.web.client.RestClient;
@Service public class RiskClient{private final RestClient.Builder client;private final boolean forceFail;public RiskClient(@LoadBalanced RestClient.Builder client,@Value("${bank.risk.force-failure:false}") boolean forceFail){this.client=client;this.forceFail=forceFail;}
@CircuitBreaker(name="customerRisk",fallbackMethod="fallback") @Retry(name="customerRisk") public String risk(long customerId,String authorization){if(forceFail)throw new IllegalStateException("Falla simulada del servicio de clientes");Map body=client.build().get().uri("http://customer-service/api/customers/{id}/risk",customerId).header("Authorization",authorization).retrieve().body(Map.class);return body==null?"UNKNOWN":String.valueOf(body.get("riskLevel"));}
String fallback(long customerId,String authorization,Throwable ex){return "UNKNOWN";}}
